class RobotFSM:
    def __init__(self):
        self.state = 'FORWARD'

    def update(self, distance_sensor):
        if self.state == 'FORWARD':
            print('Moviendo hacia adelante...')
            if distance_sensor < 20:  # Evento disparador
                self.state = 'STOP'
        elif self.state == 'STOP':
            print('¡Obstáculo detectado! Deteniendo motores...')
            self.state = 'ROTATE'
        elif self.state == 'ROTATE':
            print('Rotando para evadir...')
            # Simulamos que tras rotar, el camino está libre
            self.state = 'FORWARD'
